  failed = [r["case"] for r in res if not r["pass"]]
  return {"ok": not failed, "passed": len(res) - len(failed),
          "failed": failed, "results": res}

def out(obj, code=0):
  print(json.dumps(obj, indent=2, ensure_ascii=False))
  return code

def main(argv=None):
  ap = argparse.ArgumentParser(prog="relay.py")
  ap.add_argument("--home")  # else $RELAY_HOME
  ap.add_argument("--dry-run", action="store_true")  # write POSTs to <home>/outbox/
  sp = ap.add_subparsers(dest="cmd", required=True)
  for c in ("version", "status", "selftest"):
    sp.add_parser(c)
  p = sp.add_parser("init")
  p.add_argument("--name")
  p.add_argument("--url-env")  # default RELAY_SELF_URL
  p.add_argument("--auth-env")  # default RELAY_SELF_AUTH
  p.add_argument("--refresh", action="store_true")  # re-read after key rotation
  p.add_argument("--force", action="store_true")  # new identity
  isp = sp.add_parser("invite").add_subparsers(dest="sub", required=True)
  p = isp.add_parser("create")
  p.add_argument("--hours", type=float, default=24)
  p.add_argument("--qr")  # QR PNG path
  isp.add_parser("list")
  isp.add_parser("cancel").add_argument("invite_id")
  p = sp.add_parser("accept")
  p.add_argument("--env", default="RELAY_INVITE_IN")
  p.add_argument("--invite-stdin", action="store_true")
  sp.add_parser("receive").add_argument("--file")
  p = sp.add_parser("send")
  p.add_argument("contact")
  g = p.add_mutually_exclusive_group(required=True)
  g.add_argument("--text")
  g.add_argument("--text-file")
  p.add_argument("--approved", action="store_true")  # owner OKed this exact text
  csp = sp.add_parser("contacts").add_subparsers(dest="sub", required=True)
  csp.add_parser("list")
  csp.add_parser("remove").add_argument("contact")
  p = csp.add_parser("set-auto-send")
  p.add_argument("contact")
  p.add_argument("state", choices=["on", "off"])
  sp.add_parser("qr-decode").add_argument("image")
  a = ap.parse_args(argv)
  try:
    if a.cmd == "version":
      return out({"ok": True, "version": VERSION})
    if a.cmd == "selftest":
      r = selftest()
      return out(r, 0 if r["ok"] else 1)
    if a.cmd == "qr-decode":
      return out(qr_decode(a.image))
    R = Relay(a.home or os.environ.get("RELAY_HOME"), dry_run=a.dry_run)
    if a.cmd == "status":
      return out(R.status())
    if a.cmd == "init":
      return out(R.init(a.name, a.url_env, a.auth_env, a.refresh, a.force))
    if a.cmd == "invite":
      return out(R.invite_create(a.hours, a.qr) if a.sub == "create" else
                 R.invite_list() if a.sub == "list" else R.invite_cancel(a.invite_id))
    if a.cmd == "accept":
      line = sys.stdin.read() if a.invite_stdin else os.environ.get(a.env, "")
      if not line.strip():
        raise RelayError("no_invite: put the invite in masked input %s" % a.env)
      return out(R.accept(line))
    if a.cmd == "receive":
      f = open(a.file, "rb") if a.file else sys.stdin.buffer
      with f:
        return out(R.receive(f.read(2 * MAX_BODY + 1)))
    if a.cmd == "send":
      text = a.text
      if a.text_file:
        with open(a.text_file, encoding="utf-8") as f:
          text = f.read(4 * MAX_TEXT)
      return out(R.send(a.contact, text, a.approved))
    if a.sub == "list":
      return out({"ok": True, "contacts": [R.public(k, v) for k, v in R.contacts().items()]})
    return out(R.contacts_edit(a.contact, remove=a.sub == "remove", auto=a.state == "on"
                               if a.sub == "set-auto-send" else None))
  except RelayError as e:
    return out({"ok": False, "error": str(e).split(":")[0], "detail": str(e)}, 1)
  except OSError as e:
    return out({"ok": False, "error": "io_error", "detail": type(e).__name__}, 1)

if __name__ == "__main__":
  sys.exit(main())
